865	// ones are built with the program (see emit::LIB_COPIES).
866	const LIB_COPY_BYTES: usize = 32_000;
867	
868	// The copies compiled into the cached library: the large ones, and every copy they import (directly or not), since
869	// the library's modules start before the program's and so can only import each other. Small copies only the
870	// program or a re-export shim imports are left to the program.
871	fn lib_copies(own: &HashSet<String>) -> Vec<String> {
872	    let mut lib: std::collections::BTreeSet<String> = own.iter().filter(|m| sandbox_module(m).is_some_and(|t| t.len() >= LIB_COPY_BYTES)).cloned().collect();
873	    loop {
874	        let mut more = vec![];
875	        for m in &lib {
876	            for line in sandbox_module(m).unwrap_or("").lines() {
877	                let l = line.trim_start();
