905	fn runtime_lib(cache: &Path, rustc_v: &str) -> Result<PathBuf, String> {
906	    let dir = cache.join("dynrt").join(format!("{:016x}", fnv(&[RUNTIME, rustc_v])));
907	    let lib = dir.join("libbrevi_dyn.rlib");
908	    if lib.exists() {
909	        return Ok(lib);
910	    }
911	    std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
912	    // programs built side by side wait for one build of the runtime instead of each building it
913	    let lock = dir.join(".lock");
914	    let owned = crate::build_lock(&lock, &|| lib.exists());
915	    let r = runtime_lib_build(&dir, &lib);
916	    if owned {
917	        std::fs::remove_file(&lock).ok();
918	    }
