    first = field_name[:i]
    if first.isdecimal():
        first = int(first)

    def rest():
        j = i
        while j < n:
            if field_name[j] == '.':
                j += 1
                start = j
                while j < n and field_name[j] != '.' and field_name[j] != '[':
