    except Exception as e:
        print(type(e).__name__, str(e))

# errors
for s in ['$', '$$$', 'foo $ bar', '$ who', '${}', '${x', '${x!}', 'foo\n$bar\nbaz']:
    try:
        Template(s).substitute()
    except Exception as e:
        print('T', repr(s), type(e).__name__, str(e))
    try:
        print('valid', repr(s), Template(s).is_valid())
    except Exception as e:
        print('V', repr(s), type(e).__name__, str(e))

