class Percent(Template):
    delimiter = '%'
print(Percent('100% %a %%b').substitute(a='x'))
class Braced(Template):
    delimiter = '$'
    braceidpattern = r'[a-z]+'
print(Braced('${who} $who').substitute(who='x'))

